               <div class=\"col-12 mt-1\">\n                        <input type=\"checkbox\" class=\"checkbox\" :id=\"$id('bypass_cache_archives')\" v-model=\"settings.bypass_cache.archives\" :disabled=\"isLoading || isSaving\">\n                        <label class=\"font-weight-normal\" :for=\"$id('bypass_cache_archives')\" v-text=\"$wp.trans('bypass_cache_archives')\"></label>\n                    </div>\n                    <div class=\"col-12 mt-1\">\n                        <input type=\"checkbox\" class=\"checkbox\" :id=\"$id('bypass_cache_tag')\" v-model=\"settings.bypass_cache.tag\" :disabled=\"isLoading || isSaving\">\n                        <label class=\"font-weight-normal\" :for=\"$id('bypass_cache_tag')\" v-text=\"$wp.trans('bypass_cache_tag')\"></label>\n                    </div>\n                    <div class=\"col-12 mt-1\">\n                        <input type=\"checkbox\" class=\"checkbox\" :id=\"$id('bypass_cache_category')\" v-model=\"settings.bypass_cache.category\" :disabled=\"isLoading || isSaving\">\n                        <label class=\"font-weight-normal\" :for=\"$id('bypass_cache_category')\" v-text=\"$wp.trans('bypass_cache_category')\"></label>\n                    </div>\n                    <div class=\"col-12 mt-1\">\n                        <input type=\"checkbox\" class=\"checkbox\" :id=\"$id('bypass_cache_feed')\" v-model=\"settings.bypass_cache.feed\" :disabled=\"isLoading || isSaving\">\n                        <label class=\"font-weight-normal\" :for=\"$id('bypass_cache_feed')\" v-text=\"$wp.trans('bypass_cache_feed')\"></label>\n                    </div>\n                    <div class=\"col-12 mt-1\">\n                        <input type=\"checkbox\" class=\"checkbox\" :id=\"$id('bypass_cache_search')\" v-model=\"settings.bypass_cache.search\" :disabled=\"isLoading || isSaving\">\n                        <label class=\"font-weight-normal\" :for=\"$id('bypass_cache_search')\" v-text=\"$wp.trans('bypass_cache_search')\"></label>\n                    </div>\n                    <div class=\"col-12 mt-1\">\n                        <input type=\"checkbox\" class=\"checkbox\" :id=\"$id('bypass_cache_author')\" v-model=\"settings.bypass_cache.author\" :disabled=\"isLoading || isSaving\">\n                        <label class=\"font-weight-normal\" :for=\"$id('bypass_cache_author')\" v-text=\"$wp.trans('bypass_cache_author')\"></label>\n                    </div>\n                </div>\n\n                <div class=\"row mt-3\">\n                    <div class=\"col-12 my-2\">\n                        <label :for=\"$id('rejected_uri')\">{{ $wp.trans('rejected_uri') }}</label>\n\n                        <p class=\"description\" v-text=\"$wp.trans('rejected_uri_description')\"></p>\n                        <textarea :id=\"$id('rejected_uri')\" class=\"large-text ltr\" v-model=\"settings.rejected_uri\" rows=\"7\" cols=\"15\" :placeholder=\"$wp.trans('rejected_uri_placeholder')\"></textarea>\n                        <p class=\"description\" v-text=\"$wp.trans('rejected_uri_wildcard')\"></p>\n                    </div>\n                </div>\n\n                <div class=\"row mt-3\">\n                    <div class=\"col-12 my-2\">\n                        <label :for=\"$id('rejected_user_agent')\">{{ $wp.trans('rejected_user_agent') }}</label>\n\n                        <p class=\"description\" v-text=\"$wp.trans('rejected_user_agent_description')\"></p>\n                        <textarea :id=\"$id('rejected_user_agent')\" class=\"large-text ltr\" v-model=\"settings.rejected_user_agent\" rows=\"7\" cols=\"15\" :placeholder=\"$wp.trans('rejected_user_agent_placeholder')\"></textarea>\n                    </div>\n                </div>\n\n                <div class=\"row mt-3\">\n                    <div class=\"col-12 my-2\">\n                        <label :for=\"$id('rejected_cookies')\">{{ $wp.trans('rejected_cookies') }}</label>\n\n                        <p class=\"description\" v-text=\"$wp.trans('rejected_cookies_description')\"></p>\n                        <textarea :id=\"$id('rejected_cookies')\" class=\"large-text ltr\" v-model=\"settings.rejected_cookies\" rows=\"7\" cols=\"15\" :placeholder=\"$wp.trans('rejected_cookies_placeholder')\"></textarea>\n                    </div>\n                </div>\n            </TogglePanel>\n\n            <p class=\"submit\">\n                <button type=\"submit\" class=\"wpb-button wpb-button-lg wpb-button-primary\" :disabled=\"isLoading || isSaving || isDeleting\">\n                    <Loader v-if=\"isSaving\" color=\"#fff\"></Loader>\n                    <svg v-else viewBox=\"0 0 24 24\">\n                        <path d=\"M15,9H5V5H15M12,19A3,3 0 0,1 9,16A3,3 0 0,1 12,13A3,3 0 0,1 15,16A3,3 0 0,1 12,19M17,3H5C3.89,3 3,3.9 3,5V19A2,2 0 0,0 5,21H19A2,2 0 0,0 21,19V7L17,3Z\" />\n                    </svg>\n                    {{ $wp.trans('save_settings') }}\n                </button>\n            </p>\n\n            <p v-if=\"!isSaving && !isLoading\">\n                <button type=\"button\" class=\"wpb-button wpb-button-sm wpb-button-outlined wpb-button-danger wpb-button-noborder\" :disabled=\"isLoading || isSaving || isDeleting\" @click=\"deleteSettings\">\n                    <Loader v-if=\"isDeleting\" color=\"#fff\"></Loader>\n                    <svg v-else viewBox=\"0 0 24 24\">\n                        <path d=\"M9,3V4H4V6H5V19A2,2 0 0,0 7,21H17A2,2 0 0,0 19,19V6H20V4H15V3H9M7,6H17V19H7V6M9,8V17H11V8H9M13,8V17H15V8H13Z\" />\n                    </svg>\n                    {{ $wp.trans('reset_settings') }}\n                </button>\n            </p>\n        </form>\n    </div>\n</template>\n\n<script>\n    import Loader from \"../Components/Loader\";\n    import TogglePanel from \"../Components/TogglePanel\";\n    import API from \"../Utilities/Api\";\n\n    export default {\n        components: {Loader, TogglePanel},\n        data() {\n            return {\n                isLoading: true,\n                isSaving: false,\n                isDeleting: false,\n\n                settings: {\n                    bypass_cache: {\n                        single: null,\n                        pages: null,\n                        frontpage: null,\n                        home: null,\n                        archives: null,\n                        tag: null,\n                        category: null,\n                        feed: null,\n                        search: null,\n                        author: null\n                    },\n                    rejected_uri: null,\n                    rejected_user_agent: null,\n                }\n            };\n        },\n        async mounted() {\n            this.isLoading = true;\n\n            try {\n                let response = await API.get('settings');\n                this.settings = Object.assign(this.settings, response.data.data);\n            } catch(error) {\n                console.error(error)\n            }\n\n            this.isLoading = false;\n        },\n        methods: {\n            async deleteSettings() {\n                let results = await this.confirm(this.$wp.trans('reset_settings'), this.$wp.trans('confirm_reset_settings'), 'danger', this.$wp.trans('reset'));\n                if(!results.value) {\n                    return;\n                }\n\n                this.isDeleting = true;\n\n                try {\n                    let response = await API.delete('settings');\n                    this.settings = Object.assign(this.settings, response.data.data)\n                    this.toast(this.$wp.trans('settings_saved'), 'success')\n                } catch (e) {\n                    console.error(e);\n                    this.toast(this.$wp.trans('error_saving_settings') + ':' + e.message, 'error');\n                }\n\n                this.isDeleting = false;\n            },\n            async saveSettings() {\n                this.isSaving = true;\n\n                try {\n                    await API.patch('settings', this.settings);\n                    this.toast(this.$wp.trans('settings_saved'), 'success')\n                } catch (e) {\n                    console.error(e);\n                    this.toast(this.$wp.trans('error_saving_settings') + ':' + e.message, 'error');\n                }\n\n                this.isSaving = false;\n            },\n            updateSettings(value, ...fields) {\n                for(let field of fields) {\n                    this.settings.bypass_cache[field] = value;\n                }\n            }\n        }\n    };\n</script>\n\n<style>\n    .widget + .widget {\n        margin-top: 40px;\n    }\n</style>\n"],"sourceRoot":""}]);
